DO $$ DECLARE rec record; BEGIN FOR rec IN SELECT pp.oid::regprocedure sig FROM pg_proc pp JOIN pg_depend d ON d.objid=pp.oid AND d.classid='pg_proc'::regclass JOIN pg_extension e ON e.oid=d.refobjid WHERE e.extname='http' LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',rec.sig); END LOOP; END $$; ALTER FUNCTION public.update_user_streak(uuid) SECURITY INVOKER; ALTER FUNCTION public.update_team_benefits(uuid) SECURITY INVOKER;
